// CATALOG.md: what the test world holds and what each piece is there for. Generated by
// `npm run world:update` from the parts and their PURPOSE tables; world.test.mjs fails while
// it is stale.

import prettier from "prettier";
import { buildExampleWorld, PARTS } from "./index.mjs";
import { PURPOSE as BASE_PURPOSE } from "./parts/base.mjs";
import { PURPOSE as EDGE_PURPOSE } from "./parts/edge.mjs";
import { PURPOSE as GOLD_PURPOSE } from "./parts/gold.mjs";
import { NAMED as LARGE_NAMED, PURPOSE as LARGE_PURPOSE } from "./parts/large.mjs";

export const CATALOG_FILE = "tests/world/CATALOG.md";

/** The purpose of every entry, per part. */
export const PURPOSES = {
  base: BASE_PURPOSE,
  edge: EDGE_PURPOSE,
  gold: GOLD_PURPOSE,
  large: LARGE_PURPOSE,
};

const cell = (text) => String(text ?? "").replaceAll("|", "\\|");

/** Which part each id comes from: the base world first, every later part after it. */
export function partOfIds() {
  const owner = new Map();
  let built = [];
  for (const part of PARTS) {
    const include = PARTS.slice(0, PARTS.indexOf(part) + 1);
    const world = buildExampleWorld("de", { include });
    const ids = everyId(world);
    for (const id of ids) if (!owner.has(id) && !built.includes(id)) owner.set(id, part);
    built = ids;
  }
  return owner;
}

/** Every id the world gives out that a catalog row can stand for. */
function everyId({ manuscript, figures, storyboards }) {
  return [
    ...figures.nodes.map((node) => node.id),
    ...manuscript.chapters.map((chapter) => chapter.id),
    ...manuscript.trash.map((entry) => entry.chapter.id),
    ...storyboards.boards.map((board) => board.id),
    ...storyboards.nodes.map((card) => card.id),
  ];
}

export async function renderCatalog() {
  const world = buildExampleWorld("de", { include: PARTS });
  const owner = partOfIds();
  const purpose = (id) => PURPOSES[owner.get(id)]?.[id] ?? "";
  const table = (head, rows) => [
    `| ${head.join(" | ")} |`,
    `| ${head.map(() => "---").join(" | ")} |`,
    ...rows.map((row) => `| ${row.map(cell).join(" | ")} |`),
  ];
  const { manuscript, figures, storyboards } = world;
  // The large part is listed one by one only for its named entries; the rest is counted in
  // its own section (F-339-6).
  const listed = (id) => !id.startsWith("l-") || LARGE_NAMED.has(id);
  const large = (list) => list.filter((entry) => entry.id.startsWith("l-"));
  const lines = [
    "# Test world catalog",
    "",
    "Generated from `tests/world/` by `npm run world:update`. Do not edit; change the parts and",
    "their `PURPOSE` tables instead. Names are the German texts. The base part is photographed",
    "for the README and ships as the example world; the edge part (ids `x-...`) and the gold",
    "part (ids `g-...`) never do.",
    "",
    "## Elements",
    "",
    ...table(
      ["Id", "Part", "Kind", "Name", "Purpose"],
      figures.nodes
        .filter((node) => listed(node.id))
        .map((node) => [
          `\`${node.id}\``,
          owner.get(node.id),
          node.type,
          node.name,
          purpose(node.id),
        ]),
    ),
    "",
    "## Chapters",
    "",
    ...table(
      ["Id", "Part", "Where", "Title", "Purpose"],
      [
        ...manuscript.chapters.map((chapter) => {
          const item = manuscript.structure.items.find((entry) => entry.chapterId === chapter.id);
          return [
            `\`${chapter.id}\``,
            owner.get(chapter.id),
            item?.parentFolderId ?? "",
            chapter.title,
            purpose(chapter.id),
          ];
        }),
        ...manuscript.trash.map((entry) => [
          `\`${entry.chapter.id}\``,
          owner.get(entry.chapter.id),
          "bin",
          entry.chapter.title,
          purpose(entry.chapter.id),
        ]),
      ],
    ),
    "",
    "## Moments",
    "",
    ...table(
      ["Id", "Time", "Title"],
      figures.timeline
        .filter((moment) => listed(moment.id))
        .map((moment) => [`\`${moment.id}\``, moment.time, moment.title]),
    ),
    "",
    "## gold – KI-Goldset",
    "",
    "The AI gold set (T-289): five chapters, each built around one trap for an extraction",
    "model, and what a model is expected to propose from them (`world.evaluation.gold`).",
    "`g-wilm-ghost` and the moments `g-t-death`, `g-t-later`, `g-t-a` and `g-t-b` are the",
    "time traps of T-290; they never enter a measurement world.",
    "",
    ...table(
      ["Id", "Task", "Chapter", "Category", "Need", "Stands for"],
      (world.evaluation?.gold ?? []).map((entry) => [
        `\`${entry.id}\``,
        entry.task,
        entry.chapterId ?? "",
        entry.category,
        entry.need,
        entry.ref ?? entry.names.split("|")[0],
      ]),
    ),
    "",
    "## large – realistic size",
    "",
    "A world of the size an author works with (T-339): a novel of 28 chapters generated from",
    "the closed sentence bank of `texts/large.<lang>.mjs` with a fixed seed, and enough",
    "elements, relationships, moments and cards that every document lies far above the size",
    "at which a proxy starts to compress. Only its chapters, folder, map, boards and first 20",
    "people are listed above; the rest is counted here. `world.ids.large` lists every id.",
    "",
    ...table(
      ["Collection", "Count", "Ids"],
      [
        [
          "people",
          large(figures.nodes).filter((node) => node.type === "person").length,
          "`l-p-01` … `l-p-80`",
        ],
        [
          "organisations",
          large(figures.nodes).filter((node) => node.type === "organisation").length,
          "`l-o-01` … `l-o-10`",
        ],
        [
          "objects",
          large(figures.nodes).filter((node) => node.type === "objekt").length,
          "`l-g-01` … `l-g-10`",
        ],
        [
          "places on the map",
          large(figures.nodes).filter((node) => node.parentPlaceId === "l-map").length,
          "`l-ort-01` … `l-ort-59`",
        ],
        ["relationships", large(figures.edges).length, "`l-e-001` … `l-e-250`"],
        ["moments", large(figures.timeline).length, "`l-t-001` … `l-t-300`"],
        ["presence", large(figures.presence).length, "`l-pr-001` … `l-pr-150`"],
        ["cards", large(storyboards.nodes).length, "`l-card-plot-001` … `l-card-cast-150`"],
        ["chapters", large(manuscript.chapters).length, "`l-ch-01` … `l-ch-28`"],
      ],
    ),
    "",
    "## Storyboards",
    "",
    ...table(
      ["Id", "Part", "Board", "Kind", "Label or target", "Purpose"],
      [
        ...storyboards.boards.map((board) => [
          `\`${board.id}\``,
          owner.get(board.id),
          "",
          "board",
          board.title,
          purpose(board.id),
        ]),
        ...storyboards.nodes
          .filter((card) => listed(card.id))
          .map((card) => [
            `\`${card.id}\``,
            owner.get(card.id),
            card.boardId,
            card.kind,
            card.target ? `${card.target.kind}:${card.target.id}` : card.label,
            purpose(card.id),
          ]),
      ],
    ),
    "",
  ];
  const options = (await prettier.resolveConfig(CATALOG_FILE)) ?? {};
  const formatted = await prettier.format(lines.join("\n"), { ...options, parser: "markdown" });
  return Buffer.from(formatted, "utf8");
}
